import { NextResponse } from "next/server";
import { pool } from "../../lib/db";

export async function POST(req: Request) {
  try {
    const body = await req.json();

    // استخراج المتغيرات مع وضع قيم افتراضية null لتجنب undefined
    const part_name = body.part_name ?? null;
    const make = body.make ?? null;
    const model = body.model ?? null;
    const year = body.year !== "" && body.year !== undefined ? body.year : null;
    const vin = body.vin !== "" && body.vin !== undefined ? body.vin : null;
    const price = body.price !== "" && body.price !== undefined ? body.price : null;
    const image_url = body.image_url !== "" && body.image_url !== undefined ? body.image_url : null;

    if (!part_name || !make || !model || price === null) {
      return NextResponse.json({ error: "اسم القطعة والشركة والموديل والسعر مطلوبة" }, { status: 400 });
    }

    await pool.execute(
      "INSERT INTO parts (part_name, make, model, year, vin, price, image_url) VALUES (?, ?, ?, ?, ?, ?, ?)",
      [part_name, make, model, year, vin, price, image_url]
    );

    return NextResponse.json({ message: "تمت إضافة القطعة بنجاح" });
  } catch (error: any) {
    console.error("Error adding part:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}